interface SeriesConfig {
  key: string;
  label: string;
  color: string;
  max?: number;
}

function MiniChart({ data, series, height = 160 }: {
  data: HistoryEntry[];
  series: SeriesConfig[];
  height?: number;
}) {
  if (data.length < 2) {
    return (
      <div className="flex items-center justify-center text-muted-foreground text-xs" style={{ height }}>
        {t('vital.t25337')}
      <div>
    );
